import { expect, test } from '@playwright/test';

/**
 * Real renderer acceptance checks. Run against the Vite DEV server:
 *   npm run test:e2e:dev -- --grep "split export pixels"
 *
 * playright.dev.config.ts includes verified-asset-* source-import tests.
 * The fixture is generated by the browser; no customer photo or cloud needed.
 * This checks exported decoded PNG bytes, NOT the separate CSS editor preview.
 */
const variants = [
  { name: 'neutral crop', rotateDeg: 0, flipH: false, flipV: false, zoom: 1, panX: 0, panY: 0 },
  { name: 'zoom and reposition', rotateDeg: 0, flipH: false, flipV: false, zoom: 1.3, panX: -12, panY: 7 },
  { name: 'flipped and panned', rotateDeg: 0, flipH: true, flipV: true, zoom: 1.1, panX: 8, panY: -6 },
  { name: 'rotated 90 degrees', rotateDeg: 90, flipH: false, flipV: false, zoom: 1.2, panX: 6, panY: -4 },
  { name: 'rotated 270 degrees and flipped', rotateDeg: 270, flipH: true, flipV: false, zoom: 1.1, panX: -4, panY: 6 },
] as const;

for (const variant of variants) {
  test('split export pixels reproduce the one-pass combined PNG: ' + variant.name, async ({ page }) => {
    await page.goto('/');
    const output = await page.evaluate(async (settings) => {
      // The default built preview does not serve TypeScript source URLs.
      // @ts-ignore Browser module resolved by Vite dev server.
      const { renderV2Export } = await import('/src/v2/engineClient/renderV2Export.ts');
      // @ts-ignore Browser module resolved by Vite dev server.
      const { DEFAULT_CROP } = await import('/src/v2/engineClient/cropOps.ts');

      const original = document.createElement('canvas');
      original.width = 1200;
      original.height = 640;
      const context = original.getContext('2d', { willReadFrequently: true });
      if (!context) throw new Error('Synthetic photo canvas unavailable');

      // Uneven, opaque colour bars, thin contrasting edges and shapes crossing
      // the centre make wrong pane offsets and duplicated seam pixels visible.
      context.fillStyle = '#122842';
      context.fillRect(0, 0, original.width, original.height);
      for (let x = 0; x < original.width; x += 7) {
        context.fillStyle = 'rgb(' + ((x * 11) % 256) + ',' + ((x * 3 + 37) % 256) + ',' + ((x * 5 + 13) % 256) + ')';
        context.fillRect(x, 0, 3, original.height);
      }
      context.strokeStyle = '#fff4dc';
      context.lineWidth = 5;
      context.beginPath();
      context.moveTo(0, 11);
      context.lineTo(1200, 619);
      context.stroke();
      context.fillStyle = '#ff004e';
      context.fillRect(560, 180, 110, 270);

      const image = new Image();
      image.src = original.toDataURL('image/png');
      await image.decode();

      const frame = {
        id: 'fixture-1', filename: 'split-fixture.png', isDemo: true,
        edit: { exposure: 0, warmth: 0, colour: 0 },
      } as Parameters<typeof renderV2Export>[1];
      const profile = { id: 'uat', label: 'UAT PNG', prefix: 'uat_', width: 0,
        height: 0, quality: 1, format: 'png' as const };
      const crop = { ...DEFAULT_CROP, ...settings };
      const date = new Date('2026-11-23T12:00:00.000Z');

      // Same SOURCE, edit, crop, physical combined dimensions and output format.
      // The only distinction is whether the engine publishes one or two files.
      const combined = await renderV2Export(image, frame, { width: 400, height: 160 },
        crop, profile, null, date, undefined, 1);
      const split = await renderV2Export(image, frame, { width: 200, height: 160 },
        crop, profile, null, date, undefined, 2);

      async function readPixels(file: File) {
        const bitmap = await createImageBitmap(file);
        try {
          const canvas = document.createElement('canvas');
          canvas.width = bitmap.width;
          canvas.height = bitmap.height;
          const ctx = canvas.getContext('2d', { willReadFrequently: true });
          if (!ctx) throw new Error('Exported photo pixel inspection unavailable');
          ctx.drawImage(bitmap, 0, 0);
          const pixels = ctx.getImageData(0, 0, canvas.width, canvas.height);
          return { width: canvas.width, height: canvas.height, bytes: pixels.data };
        } finally {
          bitmap.close();
        }
      }

      const whole = await readPixels(combined.file);
      const left = await readPixels(split.sections?.[0] ?? split.file);
      const right = await readPixels(split.sections?.[1] ?? split.file);
      let mismatchedChannels = 0;
      let firstMismatch = '';
      if (whole.width === left.width + right.width &&
          left.width === right.width && whole.height === left.height && left.height === right.height) {
        for (let y = 0; y < whole.height; y++) {
          for (let x = 0; x < whole.width; x++) {
            const side = x < left.width ? left : right;
            const sideX = x < left.width ? x : x - left.width;
            const i = (y * whole.width + x) * 4;
            const j = (y * side.width + sideX) * 4;
            for (let channel = 0; channel < 4; channel++) {
              if (whole.bytes[i + channel] !== side.bytes[j + channel]) {
                mismatchedChannels++;
                if (!firstMismatch) firstMismatch = 'pixel (' + x + ',' + y + '), channel ' + channel +
                  ': combined ' + whole.bytes[i + channel] + ' versus split ' + side.bytes[j + channel];
              }
            }
          }
        }
      }
      return {
        combined: { width: whole.width, height: whole.height },
        left: { width: left.width, height: left.height },
        right: { width: right.width, height: right.height },
        sectionNames: split.sections?.map((file: File) => file.name) ?? [],
        mismatchedChannels, firstMismatch, combinedCapped: combined.capped, splitCapped: split.capped,
      };
    }, variant);

    expect(output.combined).toEqual({ width: 400, height: 160 });
    expect(output.left).toEqual({ width: 200, height: 160 });
    expect(output.right).toEqual({ width: 200, height: 160 });
    expect(output.sectionNames).toEqual([
      'uat_split-fixture-01-of-02.png',
      'uat_split-fixture-02-of-02.png',
    ]);
    expect(output.combinedCapped).toBe(false);
    expect(output.splitCapped).toBe(false);
    expect(output.mismatchedChannels, output.firstMismatch).toBe(0);
  });
}

test('split export pixels use a separate non-occluding border on each numbered output', async ({ page }) => {
  await page.goto('/');
  const checked = await page.evaluate(async () => {
    // @ts-ignore Browser module resolved by Vite dev server.
    const { renderV2Export } = await import('/src/v2/engineClient/renderV2Export.ts');
    // @ts-ignore Browser module resolved by Vite dev server.
    const { DEFAULT_CROP } = await import('/src/v2/engineClient/cropOps.ts');

    const canvas = document.createElement('canvas');
    canvas.width = 1200; canvas.height = 640;
    const context = canvas.getContext('2d');
    if (!context) throw new Error('Cannot generate test photo');
    context.fillStyle = '#3c667e'; context.fillRect(0, 0, 1200, 640);
    context.fillStyle = '#b61545'; context.fillRect(500, 0, 200, 640);
    const source = new Image();
    source.src = canvas.toDataURL('image/png');
    await source.decode();
    const frame = { id: 'synthetic', filename: 'border-fixture.png', isDemo: true,
      edit: { exposure: 0, warmth: 0, colour: 0 },
    } as Parameters<typeof renderV2Export>[1];
    const profile = { id: 'uat', label: 'PNG', prefix: '', width: 0,
      height: 0, quality: 1, format: 'png' as const };
    const border = [216, 203, 185]; // #d8cbb9
    const placements = ['all', 'horizontal', 'vertical'] as const;
    const output = [];
    for (const placement of placements) {
      const result = await renderV2Export(source, frame, { width: 200, height: 160 },
        { ...DEFAULT_CROP, borderWidth: 5, borderColour: '#d8cbb9', borderPlacement: placement },
        profile, null, new Date('2026-11-23T12:00:00.000Z'), undefined, 2);
      const sides = [];
      for (const file of result.sections ?? []) {
        const image = await createImageBitmap(file);
        try {
          const piece = document.createElement('canvas');
          piece.width = image.width; piece.height = image.height;
          const ctx = piece.getContext('2d', { willReadFrequently: true });
          if (!ctx) throw new Error('Cannot decode split border file');
          ctx.drawImage(image, 0, 0);
          const pixels = ctx.getImageData(0, 0, image.width, image.height).data;
          const matchesBorder = (x: number, y: number) => {
            const index = (y * image.width + x) * 4;
            return border.every((value, channel) => Math.abs(pixels[index + channel] - value) <= 1) &&
              pixels[index + 3] === 255;
          };
          sides.push({ width: image.width, height: image.height,
            top: matchesBorder(100, 0), bottom: matchesBorder(100, 159),
            left: matchesBorder(0, 80), right: matchesBorder(199, 80),
            centreIsPhoto: !matchesBorder(100, 80) });
        } finally { image.close(); }
      }
      output.push({ placement, sides });
    }
    return output;
  });
  expect(checked).toHaveLength(3);
  for (const item of checked) {
    expect(item.sides).toHaveLength(2);
    for (const side of item.sides) {
      expect([side.width, side.height]).toEqual([200, 160]);
      expect(side.centreIsPhoto).toBe(true);
      if (item.placement === 'all') {
        expect([side.top, side.bottom, side.left, side.right]).toEqual([true, true, true, true]);
      } else if (item.placement === 'horizontal') {
        expect([side.top, side.bottom, side.left, side.right]).toEqual([true, true, false, false]);
      } else {
        expect([side.top, side.bottom, side.left, side.right]).toEqual([false, false, true, true]);
      }
    }
  }
});
